/// Provider 调用错误（可恢复/可提示分级，架构文档 §8）。
/// Code：auth（401/key 无效）| timeout | network | invalid-response。
/// UI 按 Code 映射 i18n 文案与内联错误条。
/// </summary>
public sealed class ProviderException : Exception
{
    public string Code { get; }

