    string ApiKeyRef,               // 凭据引用 id（空 = 无鉴权，如本地 Ollama）
    string ModelName,               // 如 gpt-4o / qwen2.5-vl:7b
    [property: JsonConverter(typeof(ModelCapabilitiesJsonConverter))]
