$asm = [System.Reflection.Assembly]::LoadFrom("$env:USERPROFILE\.nuget\packages\microsoft.windows.sdk.net.ref\10.0.19041.57\lib\net8.0\WinRT.Runtime.dll")
function Dump-Method($typeName, $methodName) {
    $t = $asm.GetType($typeName)
    if (-not $t) { Write-Output "TYPE NOT FOUND: $typeName"; return }
    $m = $t.GetMethods([System.Reflection.BindingFlags]"Public,NonPublic,Static,Instance") | Where-Object { $_.Name -eq $methodName } | Select-Object -First 1
    if (-not $m) { Write-Output "METHOD NOT FOUND: $typeName.$methodName"; return }
    $il = $m.GetMethodBody().GetILAsByteArray()
    $calls = @()
    for ($i=0; $i -lt $il.Length -and $i -lt 4000; $i++) {
        $op = $il[$i]
        # call/callvirt 0x28/0x6F, calli 0x29, newobj 0x73
        if ($op -eq 0x28 -or $op -eq 0x6F -or $op -eq 0x73) {
            $tok = [System.BitConverter]::ToInt32($il, $i+1) -band 0x00FFFFFF
            try { $target = $asm.ResolveMember($tok); $calls += "$('{0:X2}' -f $op) -> $($target.ReflectedType.Name).$($target.Name)" } catch { $calls += "0x$('{0:X2}' -f $op) -> <$($_.Exception.Message)>" }
            $i += 4
        }
    }
    Write-Output "== $typeName.$methodName =="
    $calls | ForEach-Object { Write-Output "   $_" }
}
